window.psPackStatus=id=>modalForm(T('Change Purchase Status','구매 상태 변경'),select('status','New Status','새 상태',[['Draft',T('Return to Draft','초안으로 되돌리기')],['Cancelled',T('Cancel Purchase','구매 취소')],['Closed',T('Close Purchase','구매 종결')]])+input('reason','Reason','사유','','required'),`psPackStatusSave(event,${id})`);window.psPackStatusSave=async(ev,id)=>{ev.preventDefault();if(await mutation('/purchases/'+id+'/status',formObject(ev.target)))await psPackPurchase(id)};
window.psPackReturnForm=(lineId,max,condition='accepted')=>modalForm(T('Return Materials to Supplier','공급업체에 자재 반품'),`<p>${E(T('Returns remain linked to the original receipt and reopen the delivery balance for replacement. Record a supplier credit note in Payments when a replacement is not expected.','반품은 원래 입고와 연결되고 대체 납품 잔량을 다시 엽니다. 대체품이 없는 경우 지급에서 공급업체 대변 전표를 기록하세요.'))}</p>${input('quantity','Quantity (Base Unit)','수량 (기본 단위)',max,`type="number" min="0.0001" max="${max}" step="0.0001" required`)}${input('movement_date','Return Date','반품일',new Date().toISOString().slice(0,10),'type="date" required')}${input('reason','Reason','사유','','required')}${input('valuation_reason','Finance Valuation Variance Reason (if applicable)','재무 평가 차이 사유 (해당 시)')}<input type="hidden" name="condition" value="${condition}"><input type="hidden" name="receipt_line_id" value="${lineId}">`,`psPackReturnSave(event)`);window.psPackReturnSave=async ev=>{ev.preventDefault();if(await mutation('/returns',formObject(ev.target)))await psPackPurchase(purchaseData.id,'receiving')};
window.psPackAdjustmentForm=async()=>{await getOptions();modalForm(T('Material Stock Movement','자재 재고 이동'),`<div class="pack-grid">${select('material_id','Material','자재',[['',T('Select Material','자재 선택')],...options.materials.map(m=>[m.id,m.sku+' · '+materialName(m)])],'','required')}${select('kind','Movement Type','이동 유형',['Wastage','Positive Adjustment','Negative Adjustment','Warehouse Transfer'].map(x=>[x,label(x)]),'Wastage',`onchange="psPackAdjustmentType(this)"`)}${select('location_id','From Location','출발 위치',optionsSelect(options.locations,'warehouse'),'','required')}${select('to_location_id','To Location (transfer only)','도착 위치 (이동 시)',optionsSelect(options.locations,'warehouse'),'','disabled')}${input('quantity','Quantity in Base Unit','기본 단위 수량',1,'type="number" min="0.0001" step="0.0001" required')}${input('unit_cost_krw','Positive Adjustment Unit Cost KRW','증가 조정 단가 원화','','type="number" min="0.0001" step="0.0001" disabled')}${input('movement_date','Movement Date','이동일',new Date().toISOString().slice(0,10),'type="date" required')}${input('reference','Reference','참조')}${input('reason','Reason','사유','','required')}</div>`,`psPackAdjustmentSave(event)`)};
window.psPackAdjustmentType=el=>{el.form.to_location_id.disabled=el.value!=='Warehouse Transfer';el.form.unit_cost_krw.disabled=el.value!=='Positive Adjustment';el.form.unit_cost_krw.required=el.value==='Positive Adjustment'};window.psPackAdjustmentSave=async ev=>{ev.preventDefault();if(await mutation('/adjustments',formObject(ev.target)))await go('',0,'stock')};
window.psPackLegacy=async id=>{const m=await api(base+'/legacy-purchases/'+id);document.getElementById('content').innerHTML=`<div class="pack-workspace" data-pack-legacy="${id}">${header(T('Legacy Purchase Receipt','기존 구매 입고')+' · '+(m.reference||m.id))}${panel(T('Preserved Legacy Record','보존된 기존 기록'),`<p class="muted">${E(T('This is the original combined purchase/receipt record. Its identifiers, payments and stock history are retained.','이 기록은 기존 구매 및 입고 통합 기록입니다. 식별자, 지급 및 재고 이력이 보존됩니다.'))}</p><dl class="pack-dl">${[[T('Material','자재'),m.sku+' · '+materialName(m)],[T('Supplier','공급업체'),m.supplier_name],[T('Receipt Date','입고일'),m.movement_date],[T('Quantity','수량'),N(m.quantity)+' '+m.unit],[T('Purchase Value','구매 금액'),'KRW '+N(m.purchase_krw)],[T('Reference','참조'),m.reference]].map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${E(v||'—')}</dd></div>`).join('')}</dl><div class="actions">${btn(T('Open Material','자재 열기'),`psPackNavigate('material',${m.packaging_item_id})`)}${btn(T('Open Original Movement','원본 이동 열기'),`psPackNavigate('movement',${id})`)}${m.supplier_id?btn(T('Open Supplier','공급업체 열기'),`BOMRouter.navigate('psSuppliers','supplier',${m.supplier_id},'account')`):''}${m.receipt_file?btn(T('View Evidence','증빙 보기'),`openStoredAttachmentV321('/uploads/${E(m.receipt_file)}')`):''}</div>`)}${panel(T('Existing Payments & Allocations','기존 지급 및 배정'),tables([T('Date','날짜'),T('Type','유형'),T('Amount KRW','금액 원화'),T('Status','상태')],[...m.payments.map(x=>`<tr><td><button class="pack-link" onclick="BOMPinkFX.view(${x.id})">${E(x.payment_date)}</button></td><td>${E(T('Payment','지급'))}</td><td>${N(x.allocation_krw)}</td><td>${E(label(x.status))}</td></tr>`),...m.allocations.map(x=>`<tr><td>${E(x.allocation_date)}</td><td>${E(T('Advance Allocation','선급금 배정'))}</td><td>${N(x.amount_krw)}</td><td>${E(label(x.status))}</td></tr>`)]))}</div>`};
window.psPackMovement=async id=>{const seq=++epoch,m=await api(base+'/movements/'+id);if(seq!==epoch)return;document.getElementById('content').innerHTML=`<div class="pack-workspace" data-pack-movement="${id}">${header(T('Stock Movement','재고 이동')+' · '+m.sku)}${panel(T('Immutable Movement Record','변경 불가 이동 기록'),`<dl class="pack-dl">${[[T('Movement ID','이동 ID'),m.immutable_id],[T('Material','자재'),materialName(m)],[T('Type','유형'),label(m.movement_type)],[T('Quantity','수량'),N(m.quantity)+' '+m.unit],[T('Quarantined','격리 수량'),N(m.quarantine_quantity)],[T('Location','위치'),m.warehouse],[T('Date','날짜'),m.movement_date],[T('Source Document','원본 문서'),m.reference],[T('Unit Cost KRW','단가 원화'),N(m.unit_cost_krw)],[T('Reason','사유'),m.notes],[T('User','사용자'),m.created_by]].map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${E(v||'—')}</dd></div>`).join('')}</dl>${m.purchase_id?btn(T('Open Purchase','구매 열기'),`psPackNavigate('purchase',${m.purchase_id},'receiving')`):''}${m.reference_type==='Production'?btn(T('Open Production Batch','생산 배치 열기'),`BOMRouter.navigate('psProduction','batch',${m.reference_id})`):''}`)}</div>`};
window.psPackBOMChoose=async()=>{const products=await api('/api/pink-salt/products');modalForm(T('Packaging Bill of Materials','포장재 자재 명세서'),select('product_id','Finished Product SKU','완제품 SKU',products.map(p=>[p.id,p.sku+' · '+materialName(p)]),'','required'),'psPackBOMOpen(event)')};
