window.psPackBOMForm=async id=>{await getOptions();const d=await api(base+'/bom/'+id);editData=d;lineDraft=d.lines.map(l=>({...l,unit:l.unit}));modalForm(T('Packaging BOM Revision','포장재 BOM 개정')+' · '+d.product.sku,`<div id="packBOMLines"></div>${btn(T('Add Component','구성품 추가'),'psPackBOMAdd()')}${input('reason','Revision Reason','개정 사유','','required')}<p>${E(T('Confirmed production uses this recipe. Draft planning does not consume stock.','확정된 생산은 이 배합표를 사용합니다. 초안 계획은 재고를 소비하지 않습니다.'))}</p>`,`psPackBOMSave(event,${id})`,true);renderBOM()};
function renderBOM(){document.getElementById('packBOMLines').innerHTML=lineDraft.map((l,i)=>`<div class="pack-row">${select('bom_material_'+i,'Material','자재',[['',T('Select Material','자재 선택')],...options.materials.map(m=>[m.id,m.sku+' · '+materialName(m)])],l.packaging_item_id,`onchange="psPackBOMLine(${i},'packaging_item_id',this.value)" required`)}${input('bom_qty_'+i,'Quantity per Finished Unit','완제품 단위당 수량',l.quantity_per_unit||1,`type="number" min="0.0001" step="0.0001" oninput="psPackBOMLine(${i},'quantity_per_unit',this.value)" required`)}${input('bom_unit_'+i,'Unit','단위',l.unit||'pcs',`oninput="psPackBOMLine(${i},'unit',this.value)" required`)}${btn(T('Remove','삭제'),`psPackBOMRemove(${i})`)}</div>`).join('')}
window.psPackBOMLine=(i,k,v)=>lineDraft[i][k]=v;window.psPackBOMAdd=()=>{lineDraft.push({packaging_item_id:'',quantity_per_unit:1,unit:'pcs'});renderBOM()};window.psPackBOMRemove=i=>{lineDraft.splice(i,1);renderBOM()};window.psPackBOMSave=async(ev,id)=>{ev.preventDefault();if(await mutation('/bom/'+id,{lines:lineDraft,reason:ev.target.reason.value},'PUT'))await go('',0,'stock')};
window.psPackExternalCost=async id=>{await getOptions();const suppliers=await api('/api/pink-salt/suppliers-v315');modalForm(T('Third-party Acquisition Invoice','제3자 취득 송장'),`<p>${E(T('Final acquisition cost is allocated after material receipts are complete. Costs for issued material are recognized as a reviewed price variance.','자재 입고가 완료된 후 최종 취득 원가를 배분합니다. 출고된 자재 원가는 검토된 가격 차이로 인식합니다.'))}</p>${select('supplier_id','Existing Cost Supplier','기존 비용 공급업체',optionsSelect(suppliers.filter(s=>s.active)),'','required')}${input('invoice_reference','Supplier Invoice Reference','공급업체 송장 참조','','required')}${input('cost_date','Invoice Date','송장일',new Date().toISOString().slice(0,10),'type="date" required')}${select('currency','Invoice Currency','송장 통화',['KRW','USD','PKR','EUR','JPY','CNY'].map(x=>[x,x]))}${input('recognition_rate','1 Invoice Currency = KRW','송장 통화 1 = 원화','','type="number" min="0" step="0.0001"')}${input('amount','Invoice Amount','송장 금액','','type="number" min="0.01" step="0.01" required')}${select('treatment','Classification','분류',[...treatments(),['operating',T('Operating Expense','운영 비용')]])}${select('tax_account_id','Recoverable Tax Ledger (if applicable)','공제 가능 세금 계정 (해당 시)',[['',T('Not applicable','해당 없음')],...options.tax_accounts.map(a=>[a.id,a.code+' · '+a.name])])}${input('reason','Cost and Allocation Reason','원가 및 배분 사유','','required')}`,`psPackExternalCostSave(event,${id})`)};window.psPackExternalReverse=(id,pid)=>modalForm(T('Reverse External Invoice','외부 송장 취소'),input('reason','Reason','사유','','required'),`psPackExternalReverseSave(event,${id},${pid})`);window.psPackExternalReverseSave=async(e,id,pid)=>{e.preventDefault();if(await mutation('/external-costs/'+id+'/reverse',formObject(e.target)))await psPackPurchase(pid,'overview')};
window.psPackExternalCostSave=async(e,id)=>{e.preventDefault();if(await mutation('/purchases/'+id+'/external-costs',formObject(e.target)))await psPackPurchase(id,'overview')};

