window.psPackPolicy=async()=>{const d=await api(base+'/receiving-policy');modalForm(T('Receiving Before Invoice Policy','송장 전 입고 정책'),`<p>${E(T('Choose the existing GRNI liability ledger and approved policy. Old receipts keep their original ledger.','기존 미청구 입고 부채 계정과 승인된 정책을 선택하세요. 이전 입고는 원래 계정을 유지합니다.'))}</p>${select('grni_account_id','GRNI Liability Ledger','미청구 입고 부채 계정',optionsSelect(d.accounts.map(a=>({...a,name:a.code+' · '+a.name}))),d.policy?.grni_account_id,'required')}${input('policy_reference','Approved Policy Reference','승인된 정책 참조',d.policy?.policy_reference||'','required')}${input('reason','Reason','사유','','required')}`,'psPackPolicySave(event)')};window.psPackPolicySave=async e=>{e.preventDefault();await mutation('/receiving-policy',formObject(e.target))};
let amendmentLines=[],planOutputs=[];
window.psPackAmend=async id=>{const d=await api(base+'/purchases/'+id);purchaseData=d;amendmentLines=d.lines.map(l=>({...l,line_id:l.id}));modalForm(T('Controlled Purchase Amendment','통제된 구매 개정'),`<p>${E(T('Changes preserve original receipts and create a differential Accounting proposal. Return excess goods before reducing ordered quantities.','변경은 원래 입고를 보존하고 차액 회계 제안을 생성합니다. 주문 수량을 줄이기 전에 초과 상품을 반품하세요.'))}</p>${input('effective_date','Effective Date','적용일',new Date().toISOString().slice(0,10),'type="date" required')}${input('invoice_reference','Invoice Reference','송장 참조',d.invoice_reference)}${input('reason','Amendment Reason','개정 사유','','required')}${tables([T('Material','자재'),T('Purchase Quantity','구매 수량'),T('Unit Price','단가'),T('Discount','할인'),T('Tax %','세율 %')],amendmentLines.map((l,i)=>`<tr><td>${E(l.snapshot.sku)} · ${E(l.purchase_unit)}</td>${['quantity','unit_price','discount','tax_percent'].map(k=>`<td><input type="number" min="${k==='quantity'?'0.0001':'0'}" step="0.0001" value="${l[k]}" oninput="psPackAmendLine(${i},'${k}',this.value)" required></td>`).join('')}</tr>`))}`,`psPackAmendSave(event,${id})`,true)};window.psPackAmendLine=(i,k,v)=>amendmentLines[i][k]=v;window.psPackAmendSave=async(e,id)=>{e.preventDefault();if(await mutation('/purchases/'+id+'/amend',{...formObject(e.target),revision:purchaseData.revision,lines:amendmentLines}))await psPackPurchase(id)};
window.psPackCancel=id=>modalForm(T('Controlled Purchase Cancellation','통제된 구매 취소'),`<p>${E(T('Resolve payments, credits and dependent consumption first. Existing posted journals create reversal proposals in Posting Control.','먼저 지급, 대변 전표 및 종속 소비를 해결하세요. 기존 전기 분개는 전기 관리에서 취소 제안을 생성합니다.'))}</p>${input('effective_date','Effective Date','적용일',new Date().toISOString().slice(0,10),'type="date" required')}${input('reason','Cancellation Reason','취소 사유','','required')}`,`psPackCancelSave(event,${id})`);window.psPackCancelSave=async(e,id)=>{e.preventDefault();if(await mutation('/purchases/'+id+'/cancel',{...formObject(e.target),revision:purchaseData.revision}))await psPackPurchase(id)};
window.psPackCredit=async id=>{const d=await api(base+'/purchases/'+id);purchaseData=d;const lines=d.receipts.flatMap(r=>r.lines.filter(l=>l.returned>0).map(l=>[l.id,r.receipt_no+' · '+d.lines.find(x=>x.id===l.purchase_line_id)?.snapshot.sku+' · '+N(l.returned)]));modalForm(T('Supplier Credit Note','공급업체 대변 전표'),`<p>${E(T('Use the original returned receipt. The credit reduces the payable and cancels replacement quantities; it does not deduct stock again.','원래 반품 입고를 사용하세요. 대변 전표는 미지급금과 대체 수량을 줄이며 재고를 다시 차감하지 않습니다.'))}</p>${select('receipt_line_id','Original Returned Receipt','원래 반품 입고',lines,'','required')}${input('quantity','Credited Base Quantity','대변 기본 수량',1,'type="number" min="0.0001" step="0.0001" required')}${input('credit_reference','Supplier Credit Reference','공급업체 대변 참조','','required')}${input('credit_date','Credit Date','대변일',new Date().toISOString().slice(0,10),'type="date" required')}${input('reason','Reason','사유','','required')}`,`psPackCreditSave(event,${id})`)};window.psPackCreditReverse=(id,pid)=>modalForm(T('Reverse Supplier Credit','공급업체 대변 취소'),input('reason','Reason','사유','','required'),`psPackCreditReverseSave(event,${id},${pid})`);window.psPackCreditReverseSave=async(e,id,pid)=>{e.preventDefault();if(await mutation('/credits/'+id+'/reverse',formObject(e.target)))await psPackPurchase(pid,'payments')};
window.psPackCreditSave=async(e,id)=>{e.preventDefault();if(await mutation('/purchases/'+id+'/credits',{...formObject(e.target),revision:purchaseData.revision}))await psPackPurchase(id,'payments')};
window.psPackReserveForm=async()=>{await getOptions();const products=await api('/api/pink-salt/products');options.products=products;planOutputs=[{product_id:'',quantity_units:1}];modalForm(T('Reserve Packaging for Production','생산 포장재 예약'),`${input('reference','Production Plan Reference','생산 계획 참조','','required')}${select('location_id','Warehouse / Location','창고 / 위치',optionsSelect(options.locations,'warehouse'),'','required')}<div id="packPlanLines"></div>${btn(T('Add Finished SKU','완제품 SKU 추가'),'psPackPlanAdd()')}${input('reason','Reason','사유','','required')}`,'psPackReserveSave(event)',true);renderPlan()};function renderPlan(){document.getElementById('packPlanLines').innerHTML=planOutputs.map((o,i)=>`<div class="pack-row">${select('plan_'+i,'Finished SKU','완제품 SKU',optionsSelect(options.products.map(p=>({...p,name:p.sku+' · '+materialName(p)}))),o.product_id,`onchange="psPackPlanLine(${i},'product_id',this.value)" required`)}${input('planqty_'+i,'Finished Units','완제품 수량',o.quantity_units,`type="number" min="1" step="1" oninput="psPackPlanLine(${i},'quantity_units',this.value)" required`)}${btn(T('Remove','삭제'),`psPackPlanRemove(${i})`)}</div>`).join('')};window.psPackPlanLine=(i,k,v)=>planOutputs[i][k]=v;window.psPackPlanAdd=()=>{planOutputs.push({product_id:'',quantity_units:1});renderPlan()};window.psPackPlanRemove=i=>{planOutputs.splice(i,1);renderPlan()};window.psPackReserveSave=async e=>{e.preventDefault();if(await mutation('/reservations',{...formObject(e.target),outputs:planOutputs}))await go('',0,'stock')};window.psPackRelease=id=>modalForm(T('Release Reservation','예약 해제'),input('reason','Reason','사유','','required'),`psPackReleaseSave(event,${id})`);window.psPackReleaseSave=async(e,id)=>{e.preventDefault();if(await mutation('/reservations/'+id+'/release',formObject(e.target)))await go('',0,'stock')};
window.psPackProductionReturn=async()=>{await getOptions();const d=await api(base+'/production-returns');modalForm(T('Return Unused Production Packaging','생산 미사용 포장재 반납'),`${select('usage','Original Batch / Material','원래 배치 / 자재',d.usage.filter(u=>(u.actual_used_quantity??u.quantity_used)>u.returned).map(u=>[u.production_batch_id+':'+u.packaging_item_id,u.batch_no+' · '+u.sku+' · '+T('Unreturned','미반납')+' '+N((u.actual_used_quantity??u.quantity_used)-u.returned)]),'','required')}${select('location_id','Return Location','반납 위치',optionsSelect(options.locations,'warehouse'),'','required')}${input('quantity','Unused Base Quantity','미사용 기본 수량',1,'type="number" min="0.0001" step="0.0001" required')}${input('movement_date','Return Date','반납일',new Date().toISOString().slice(0,10),'type="date" required')}${input('reason','Reason','사유','','required')}`,'psPackProductionReturnSave(event)')};window.psPackProductionReturnSave=async e=>{e.preventDefault();const b=formObject(e.target),[batch_id,material_id]=b.usage.split(':');if(await mutation('/production-returns',{...b,batch_id,material_id}))await go('',0,'stock')};
const home35=window.psPackHome;window.psPackHome=async function(...args){await home35(...args);if(document.querySelector('[data-pack-section="stock"]')){const host=document.querySelector('.pack-workspace'),d=await api(base+'/reservations');if(!document.querySelector('[data-pack-section="stock"]'))return;host.insertAdjacentHTML('beforeend',panel(T('Production Reservations','생산 예약'),d.rows.length?tables([T('Reference','참조'),T('Requirements','소요량'),T('Status','상태'),T('Actions','작업')],d.rows.map(r=>`<tr><td>${E(r.reference)}</td><td>${r.lines.map(l=>E(l.sku)+' '+N(l.quantity)+' '+E(l.unit)).join('<br>')}</td><td>${E(T(...({Reserved:['Reserved','예약됨'],Released:['Released','해제됨'],Consumed:['Consumed','소비됨']}[r.status]||[r.status,r.status])))}</td><td>${r.status==='Reserved'?btn(T('Release','해제'),`psPackRelease(${r.id})`):r.batch_id?btn(T('Open Batch','배치 열기'),`BOMRouter.navigate('psProduction','batch',${r.batch_id})`):''}</td></tr>`)):empty(),btn(T('Reserve Packaging','포장재 예약'),'psPackReserveForm()')+btn(T('Return Unused Packaging','미사용 포장재 반납'),'psPackProductionReturn()')+(me?.role==='CEO / Owner'||canDo('accounting','edit')?btn(T('Receiving Policy','입고 정책'),'psPackPolicy()'):'')))}};

// Extend the native production form, recipe and completion handler in place.
let productionRead=0;
const nativeProductionForm=window.psProductionForm,nativeRebuildProduction=window.psRebuildProdInputs;
if(nativeProductionForm)window.psProductionForm=async function(...args){await nativeProductionForm.apply(this,args);const form=document.querySelector('form[onsubmit*="psSaveProduction"]');if(!form)return;const section=document.createElement('section');section.className='card pack-panel';section.innerHTML=`<h3>${E(T('Actual Packaging Consumption','실제 포장재 소비'))}</h3><p class="muted">${E(T('Expected requirements come from the current SKU recipe. Confirm actual use and wastage; unused materials stay in stock.','예상 소요량은 현재 SKU 배합표를 따릅니다. 실제 사용량과 폐기를 확인하세요. 미사용 자재는 재고에 남습니다.'))}</p><div id="packProductionUsage"></div><input type="hidden" name="packaging_usage" value="">`;form.querySelector('.actions')?.before(section);const plans=await api(base+'/reservations');section.insertAdjacentHTML('afterbegin',select('packaging_reservation_id','Use Production Reservation (optional)','생산 예약 사용 (선택)',[['',T('No reservation','예약 없음')],...plans.rows.filter(r=>r.status==='Reserved').map(r=>[r.id,r.reference])],''));await refreshProductionPackaging()};
if(nativeRebuildProduction)window.psRebuildProdInputs=function(...args){const out=nativeRebuildProduction.apply(this,args);refreshProductionPackaging();return out};
async function refreshProductionPackaging(){const host=document.getElementById('packProductionUsage');if(!host)return;const read=++productionRead;try{const d=await api(base+'/production-preview?'+new URLSearchParams({outputs:JSON.stringify(window.psProdOutputs||[])}));if(read!==productionRead||!host.isConnected)return;host.innerHTML=d.requirements.length?tables([T('Material','자재'),T('Expected','예상량'),T('Available','사용 가능'),T('Actual Used','실제 사용'),T('Wastage','폐기'),T('Variance Reason','차이 사유')],d.requirements.map(m=>`<tr data-pack-production="${m.material_id}"><td>${E(m.sku)}<div>${E(materialName(m))}</div><small>${E(m.unit)}</small></td><td>${N(m.expected_quantity)}</td><td>${N(m.on_hand)}</td><td><input data-used type="number" min="0" step="0.0001" value="${m.expected_quantity}" oninput="psPackProductionUsage()"></td><td><input data-wasted type="number" min="0" step="0.0001" value="0" oninput="psPackProductionUsage()"></td><td><input data-reason oninput="psPackProductionUsage()"></td></tr>`)):empty();psPackProductionUsage()}catch(e){if(read===productionRead)host.textContent=e.message}}
window.psPackProductionUsage=()=>{const form=document.querySelector('form[onsubmit*="psSaveProduction"]');if(!form?.packaging_usage)return;form.packaging_usage.value=JSON.stringify([...document.querySelectorAll('[data-pack-production]')].map(row=>({packaging_item_id:Number(row.dataset.packProduction),used:Number(row.querySelector('[data-used]').value),wasted:Number(row.querySelector('[data-wasted]').value),reason:row.querySelector('[data-reason]').value})))};
const supplierProfile35=window.psSupplierAccount315;if(supplierProfile35)window.psSupplierAccount315=async function(id,...args){await supplierProfile35.call(this,id,...args);const d=await api('/api/pink-salt/suppliers/'+id+'/currency-balances-v35');if(Number(window.__ps315SupplierAccount?.supplier?.id)!==Number(id))return;const host=document.getElementById('ps315SupplierPanel')?.parentElement||document.getElementById('content');if(host&&!host.querySelector('[data-supplier-currencies]'))host.insertAdjacentHTML('beforeend',`<div data-supplier-currencies>${panel(T('Supplier Balances by Currency','통화별 공급업체 잔액'),tables([T('Currency','통화'),T('Outstanding','미결제 잔액'),T('Supplier Credit','공급업체 대변'),T('Available Advance','사용 가능한 선급금'),T('Advance Carrying KRW','선급금 장부가 원화')],d.balances.map(b=>`<tr><td>${E(b.currency)}</td><td>${N(b.outstanding)}</td><td>${N(b.supplier_credit)}</td><td>${N(b.advance_available)}</td><td>${N(b.advance_carrying_krw)}</td></tr>`)))}</div>`)};
